class Solution { public List<Integer> goodSubsetofBinaryMatrix(int[][] grid){int cols=grid[0].length,limit=1<<cols;int[] first=new int[limit];Arrays.fill(first,-1);for(int row=0;row<grid.length;row++){int mask=0;for(int col=0;col<cols;col++)mask|=grid[row][col]<<col;if(mask==0)return Arrays.asList(row);if(first[mask]==-1)first[mask]=row;}for(int a=1;a<limit;a++)if(first[a]!=-1)for(int b=a+1;b<limit;b++)if(first[b]!=-1&&(a&b)==0){int x=first[a],y=first[b];return Arrays.asList(Math.min(x,y),Math.max(x,y));}return new ArrayList<>();} }
